// Static profile site. Reads data.json (generated by scripts/site.mjs) and renders.
// No framework, no build step, no third-party runtime.

const $ = (id) => document.getElementById(id);
const el = (tag, cls, text) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
};

// Categorical palette measured from openbuild.xyz: mint / lavender / butter / ink.
const PALETTE = ['#01DB83', '#CB9BFA', '#F8FD91', '#1A1A1A', '#7CE8B8', '#E0C4FC', '#FBFEC4', '#8A8A8A', '#4A4A4A'];

const data = await fetch('data.json', { cache: 'no-cache' }).then((r) => {
  if (!r.ok) throw new Error(`data.json ${r.status}`);
  return r.json();
});

// ---------- hero ----------
$('avatar').src = data.user.avatarUrl;
$('avatar').alt = data.user.login;
$('name').textContent = data.user.name;
$('gh').href = data.user.htmlUrl;
$('headline').textContent = data.voice.headline;
$('meta').textContent = [
  data.user.hireable ? 'open to work' : null,
  data.user.login,
  `since ${data.user.createdAt.slice(0, 4)}`,
]
  .filter(Boolean)
  .join(' · ');

// ---------- conclusion ----------
$('conclusion-text').textContent = data.voice.conclusion;

// ---------- stats ----------
const stats = [
  ['repos', data.stats.ownRepos],
  ['stars', data.stats.totalStars],
  ['commits', data.contributions.commits],
  ['prs', data.contributions.pullRequests],
  ['active days', data.contributions.activeDays],
];
for (const [label, value] of stats) {
  const card = el('div', 'stat');
  card.appendChild(el('b', null, String(value)));
  card.appendChild(el('span', null, label));
  $('stats').appendChild(card);
}

// ---------- summary ----------
$('summary').textContent = data.report.summary;

// ---------- OKR ----------
for (const o of data.report.objectives) {
  const item = el('div', 'okr-item');
  item.appendChild(el('div', 'oid', o.id));
  const body = el('div');
  body.appendChild(el('h3', null, o.title));
  body.appendChild(el('p', null, `${o.kr} · ${o.data}`));
  item.appendChild(body);
  const cls = o.status === '达成' ? 'status' : o.status === '进行中' ? 'status wip' : 'status todo';
  item.appendChild(el('span', cls, o.status));
  $('okr-list').appendChild(item);
}

// ---------- projects ----------
for (const r of data.featured) {
  const card = el('div', 'project');
  const a = el('a', null, r.name);
  a.href = r.url;
  a.target = '_blank';
  a.rel = 'noopener';
  card.appendChild(a);
  card.appendChild(el('span', 'lang', r.language ?? '—'));
  card.appendChild(el('p', 'what', r.description || ''));
  card.appendChild(el('p', 'result', r.result));
  $('projects').appendChild(card);
}

// ---------- language bar ----------
const langs = data.stats.languages;
const top = langs.slice(0, 8);
const restPct = langs.slice(8).reduce((a, l) => a + l.pct, 0);
const rows = restPct > 0.05 ? [...top, { name: 'Other', pct: +restPct.toFixed(2) }] : top;
rows.forEach((l, i) => {
  const seg = el('i');
  seg.style.width = `${l.pct}%`;
  seg.style.background = PALETTE[i % PALETTE.length];
  seg.title = `${l.name} ${l.pct.toFixed(1)}%`;
  $('langbar').appendChild(seg);
});

// Legend stays at four entries; the rest is one muted line. No clutter.
rows.slice(0, 4).forEach((l, i) => {
  const item = el('li');
  const dot = el('span', 'dot');
  dot.style.background = PALETTE[i % PALETTE.length];
  item.appendChild(dot);
  item.appendChild(el('span', null, l.name));
  item.appendChild(el('span', 'pct', `${l.pct.toFixed(1)}%`));
  $('langlist').appendChild(item);
});
if (rows.length > 4) {
  const more = el('li');
  more.appendChild(el('span', 'pct', `+${rows.length - 4} more`));
  $('langlist').appendChild(more);
}

// ---------- clusters ----------
for (const c of data.clusters) {
  const card = el('div', 'cluster');
  const h = el('h3');
  h.appendChild(el('span', null, c.title));
  h.appendChild(el('em', null, String(c.repos.length)));
  card.appendChild(h);
  card.appendChild(el('p', null, c.blurb));
  const list = el('div', 'repos');
  for (const r of c.repos) {
    const a = el('a', null, r.stars > 0 ? `${r.name} ★${r.stars}` : r.name);
    a.href = r.url;
    a.target = '_blank';
    a.rel = 'noopener';
    a.title = r.description || r.name;
    list.appendChild(a);
  }
  card.appendChild(list);
  $('clusters').appendChild(card);
}

// ---------- heatmap ----------
const level = (n) => (n === 0 ? 0 : n <= 2 ? 1 : n <= 5 ? 2 : n <= 9 ? 3 : 4);
const cal = data.contributions.calendar;
const weeks = [];
for (let i = 0; i < cal.length; i += 7) weeks.push(cal.slice(i, i + 7));
const hm = $('heatmap');
for (const week of weeks) {
  for (const [date, count] of week) {
    const cell = el('i');
    cell.dataset.l = String(level(count));
    cell.title = `${date}: ${count}`;
    hm.appendChild(cell);
  }
}
const seen = new Set();
for (const [date] of cal) seen.add(date.slice(0, 7));
for (const m of [...seen].filter((_, i) => i % 2 === 0)) {
  $('months').appendChild(el('span', null, m.slice(5, 7)));
}

// ---------- cadence facts ----------
const c = data.contributions;
const facts = [
  ['窗口', `${cal[0]?.[0] ?? ''} → ${cal.at(-1)?.[0] ?? ''}`],
  ['贡献总数', String(c.total)],
  ['提交', String(c.commits)],
  ['PR / Issue', `${c.pullRequests} / ${c.issues}`],
  ['活跃日', `${c.activeDays} / ${cal.length}`],
  ['峰值', `${c.peakDay} · ${c.peakCount}`],
];
for (const [k, v] of facts) {
  const wrap = el('div');
  wrap.appendChild(el('dt', null, k));
  wrap.appendChild(el('dd', null, v));
  $('cadence-facts').appendChild(wrap);
}

// ---------- next ----------
for (const s of data.report.next) $('next').appendChild(el('li', null, s));

// ---------- footer ----------
$('footer').textContent = data.voice.footer;
$('stamp').textContent = `${data.user.login} · ${data.stats.ownRepos} repos · ${c.total} contributions / 12mo · 数据由 gh CLI 拉取 · ${data.generatedAt.slice(0, 10)}`;

// ---------- quote rotation (local, no third-party API) ----------
const quotes = data.voice.quotes ?? [];
if (quotes.length) {
  const q = $('quote');
  let qi = Math.floor(Math.random() * quotes.length);
  const show = () => {
    q.style.opacity = '0';
    setTimeout(() => {
      q.textContent = quotes[qi % quotes.length];
      q.style.opacity = '1';
      qi++;
    }, 500);
  };
  show();
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) setInterval(show, 9000);
}

// ---------- reveal on scroll ----------
const io = new IntersectionObserver(
  (entries) => {
    for (const e of entries) if (e.isIntersecting) e.target.classList.add('in');
  },
  { rootMargin: '0px 0px -10% 0px' },
);
for (const n of document.querySelectorAll('.block, .conclusion, .stats')) {
  n.classList.add('reveal');
  io.observe(n);
}
// Safety net: never leave content invisible if the observer never fires.
setTimeout(() => {
  for (const n of document.querySelectorAll('.reveal')) n.classList.add('in');
}, 1200);

// ---------- background particles ----------
const canvas = $('bg');
const ctx = canvas.getContext('2d');
let dots = [];
let raf = 0;

function resize() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = innerWidth * dpr;
  canvas.height = innerHeight * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const count = Math.min(60, Math.round((innerWidth * innerHeight) / 30000));
  dots = Array.from({ length: count }, () => ({
    x: Math.random() * innerWidth,
    y: Math.random() * innerHeight,
    vx: (Math.random() - 0.5) * 0.2,
    vy: (Math.random() - 0.5) * 0.2,
    r: Math.random() * 1.5 + 0.6,
  }));
}

function frame() {
  ctx.clearRect(0, 0, innerWidth, innerHeight);
  for (const d of dots) {
    d.x += d.vx;
    d.y += d.vy;
    if (d.x < 0 || d.x > innerWidth) d.vx *= -1;
    if (d.y < 0 || d.y > innerHeight) d.vy *= -1;
    ctx.beginPath();
    ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(1,219,131,.5)';
    ctx.fill();
  }
  for (let i = 0; i < dots.length; i++) {
    for (let j = i + 1; j < dots.length; j++) {
      const dx = dots[i].x - dots[j].x;
      const dy = dots[i].y - dots[j].y;
      const dist = Math.hypot(dx, dy);
      if (dist < 130) {
        ctx.beginPath();
        ctx.moveTo(dots[i].x, dots[i].y);
        ctx.lineTo(dots[j].x, dots[j].y);
        ctx.strokeStyle = `rgba(1,219,131,${(1 - dist / 130) * 0.2})`;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    }
  }
  raf = requestAnimationFrame(frame);
}

if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
  resize();
  addEventListener('resize', resize);
  frame();
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) cancelAnimationFrame(raf);
    else frame();
  });
} else {
  canvas.remove();
}
